import {registerCardComponent} from "@pihanga2/core";

import {ResizableComponent} from "./resizable.component";
import {RESIZABLE_CARD} from "./resizable.types";

export * from "./resizable.types";

registerCardComponent({
  name: RESIZABLE_CARD,
  component: ResizableComponent,
});

import React, {Fragment} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {clsx} from "clsx";
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable";
import {
  DefResizableHandle,
  type PiResizableHandle,
  type PiResizablePanel,
  type ResizableProps,
} from "./resizable.types";

export const ResizableComponent = (
  props: PiCardProps<ResizableProps>,
): React.ReactNode => {
  const {content, handles, direction, className, style, cardName} = props;

  const sy =
    (style as {root?: string; panel?: string; handle?: string} | undefined) ??
    {};

  const _handles: PiResizableHandle[] = Array.isArray(handles)
    ? handles
    : Array(content.length - 1).fill(handles ?? DefResizableHandle);

  function renderPanel(el: PiResizablePanel, idx: number) {
    const name = el.name ?? `panel${idx}`;
    const panelProps: {
      defaultSize: number;
      collapsible?: boolean;
      maxSize?: number;
      minSize?: number;
    } = {
      defaultSize: el.defaultSize ?? 50,
      collapsible: el.collapsible,
    };
    if (el.maxSize !== undefined) panelProps.maxSize = el.maxSize;
    if (el.minSize !== undefined) panelProps.minSize = el.minSize;

    return (
      <Fragment key={idx}>
        {renderHandle(idx)}
        <ResizablePanel
          {...panelProps}
          className={clsx(sy.panel, className && `${className}-${name}`)}
        >
          <Card cardName={el.content} parentCard={cardName} />
        </ResizablePanel>
      </Fragment>
    );
  }

  function renderHandle(idx: number) {
    if (idx === 0) return null;
    const h = _handles[idx - 1];
    return <ResizableHandle {...h} className={clsx(sy.handle)} />;
  }

  return (
    <ResizablePanelGroup
      direction={direction ?? "horizontal"}
      className={clsx(className, sy.root)}
      data-pihanga={cardName}
    >
      {content.map(renderPanel)}
    </ResizablePanelGroup>
  );
};

import {type PiCardRef, createCardDeclaration} from "@pihanga2/core";

export const RESIZABLE_CARD = "shad/resizable";

export const SdResizable =
  createCardDeclaration<ResizableProps>(RESIZABLE_CARD);

/** Convenience alias — same as {@link SdResizable}. */
export const Resizable = SdResizable;

export type ResizableProps<S = unknown> = {
  /** Ordered list of panels to render inside the resizable group. */
  content: PiResizablePanel[];
  /** Layout direction of the panel group.  Defaults to `"horizontal"`. */
  direction?: "horizontal" | "vertical";
  /**
   * Handle configuration(s) between panels.
   *
   * - A single `PiResizableHandle` is used for every handle in the group.
   * - An array must have exactly `content.length - 1` entries.
   *
   * Defaults to {@link DefResizableHandle} (visible drag handle).
   */
  handles?: PiResizableHandle | PiResizableHandle[];
  className?: string;
  /**
   * Optional Shadcn-style style overrides.
   *
   * When provided as `{ shad?: { root?: string; panel?: string; handle?: string } }`,
   * the nested class names are applied to the corresponding elements in
   * addition to any `className` already set.
   */
  style?: S;
};

export type PiResizablePanel = {
  /** Used for CSS class suffixes and stable ordering.  Defaults to `"panel{idx}"`. */
  name?: string;
  /** The card to render inside this panel. */
  content: PiCardRef;
  /** Initial size as a percentage of the group.  Defaults to `50`. */
  defaultSize?: number;
  minSize?: number;
  maxSize?: number;
  /** When `true`, the panel can be collapsed to zero size. */
  collapsible?: boolean;
};

export type PiResizableHandle = {
  /** When `true`, renders a visible drag-handle grip indicator. */
  withHandle?: boolean;
  /** When `true`, the handle is decorative only (not draggable). */
  disabled?: boolean;
};

/** Default handle configuration: visible grip, draggable. */
export const DefResizableHandle: PiResizableHandle = {
  withHandle: true,
  disabled: false,
};
